SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN (a.dischtime - a.admittime) END) AS avg_los_readmitted, AVG(CASE WHEN a.dischtime IS NULL THEN (a.edouttime - a.edregtime) END) AS avg_los_not_readmitted, CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND (a.dischtime - a.admittime) > INTERVAL '6 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_of_patients_with_long_los FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 50 AND 60 AND a.insurance = 'Medicare' AND a.admission_type = 'ED' AND a.principal_diagnosis IN ('GI bleeding');